const express = require('express');
const fs = require('fs');
const path = require('path');
const { pipeline, Transform } = require('stream');
const csvParser = require('csv-parser');
const { ExportJob } = require('../models/exportJob');

const app = express();

class CsvLeadFilterStream extends Transform {
  constructor() {
    super({ objectMode: true });
    this.isFirst = true;
  }

  _transform(row, encoding, callback) {
    if (this.isFirst) {
      this.push('LeadName,EmailAddress,Company,EstimatedDealValue\n');
      this.isFirst = false;
    }
    const line = `"${row.leadName}","${row.email}","${row.company}","${row.dealValue}"\n`;
    callback(null, line);
  }
}

app.get('/exports/csv/:exportJobId', async (req, res) => {
  if (!req.user || !req.user.organizationId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  // Validate that the export job belongs to the authenticated user's organization
  const job = await ExportJob.findOne({
    where: {
      id: req.params.exportJobId,
      organizationId: req.user.organizationId
    }
  });

  if (!job) {
    return res.status(403).json({ error: 'Access denied or export job not found' });
  }

  const exportFilePath = path.join('/data/exports', `${req.params.exportJobId}.raw.csv`);
  if (!fs.existsSync(exportFilePath)) {
    return res.status(404).json({ error: 'Export file not found' });
  }

  res.setHeader('Content-Type', 'text/csv');
  res.setHeader('Content-Disposition', 'attachment; filename="leads_export.csv"');

  const sourceStream = fs.createReadStream(exportFilePath);
  const parser = csvParser();
  const leadTransformer = new CsvLeadFilterStream();

  pipeline(sourceStream, parser, leadTransformer, res, (err) => {
    if (err && !res.headersSent) {
      res.status(500).json({ error: 'CSV export generation error' });
    }
  });
});

app.listen(8090);
